修改在库成本
如有自动记账
可在采购入库自动记账回写增加
 UPDATE storbalance sb
SET sb.cost = 
 CASE 
 WHEN sb.stornum <> 0 THEN sb.storamount / sb.stornum 
 ELSE sb.cost 
 END
WHERE EXISTS (
 SELECT 1 
 FROM purindt pi 
 WHERE pi.whid = sb.whid 
 AND pi.goodsid = sb.goodsid
 AND pi.rfbillno = p_billno
)
